CREATE TABLE roles (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(50) UNIQUE NOT NULL, protected_role boolean NOT NULL DEFAULT false);
INSERT INTO roles(name,protected_role) VALUES ('ADMIN',true),('VIEWER',true);
CREATE TABLE permissions (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(80) UNIQUE NOT NULL, display_name varchar(100) NOT NULL);
INSERT INTO permissions(name,display_name) VALUES
('manage_warehouses','Warehouses'),('manage_brands','Brands'),('manage_product_categories','Product categories'),('manage_units','Units'),('manage_products','Products'),('manage_customers','Customers'),('manage_suppliers','Suppliers'),('manage_users','Users'),('manage_roles','Roles');
CREATE TABLE role_permissions(role_id bigint REFERENCES roles(id) ON DELETE CASCADE, permission_id bigint REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='ADMIN';
ALTER TABLE app_users DROP CONSTRAINT app_users_role_check;
ALTER TABLE app_users ADD CONSTRAINT app_users_role_fk FOREIGN KEY(role) REFERENCES roles(name) ON UPDATE CASCADE;
ALTER TABLE app_users ADD COLUMN phone varchar(40) NOT NULL DEFAULT '';
ALTER TABLE app_users ADD COLUMN enabled boolean NOT NULL DEFAULT true;
CREATE TABLE brands(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL UNIQUE, description text, created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE product_categories(LIKE brands INCLUDING ALL);
CREATE TABLE base_units(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name varchar(255) NOT NULL UNIQUE,is_default integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE units(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL UNIQUE,short_name varchar(50) NOT NULL,base_unit bigint NOT NULL REFERENCES base_units(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,email varchar(254) NOT NULL UNIQUE,phone varchar(40) NOT NULL,country varchar(100) NOT NULL,city varchar(100) NOT NULL,address text NOT NULL,dob date,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE suppliers(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,email varchar(254) NOT NULL UNIQUE,phone varchar(40) NOT NULL,country varchar(100) NOT NULL,city varchar(100) NOT NULL,address text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name varchar(255) NOT NULL,code varchar(100) NOT NULL UNIQUE,product_category_id bigint NOT NULL REFERENCES product_categories(id),brand_id bigint NOT NULL REFERENCES brands(id),product_cost numeric(19,4) NOT NULL CHECK(product_cost>=0),product_price numeric(19,4) NOT NULL CHECK(product_price>=0),product_unit bigint NOT NULL REFERENCES base_units(id),sale_unit bigint REFERENCES units(id),purchase_unit bigint REFERENCES units(id),stock_alert numeric(19,4) NOT NULL DEFAULT 0 CHECK(stock_alert>=0),quantity_limit numeric(19,4) CHECK(quantity_limit>=0),order_tax numeric(7,4) NOT NULL DEFAULT 0 CHECK(order_tax BETWEEN 0 AND 100),tax_type integer NOT NULL DEFAULT 1 CHECK(tax_type IN (1,2)),barcode_symbol integer NOT NULL DEFAULT 1 CHECK(barcode_symbol BETWEEN 1 AND 5),notes text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_idx ON products(product_category_id);
CREATE INDEX products_brand_idx ON products(brand_id);
CREATE TABLE media(id uuid PRIMARY KEY,owner_type varchar(40) NOT NULL,owner_id bigint NOT NULL,mime varchar(30) NOT NULL,content bytea NOT NULL CHECK(octet_length(content)<=2097152));
CREATE INDEX media_owner_idx ON media(owner_type,owner_id);
ALTER TABLE units ADD CONSTRAINT units_id_base_unique UNIQUE(id,base_unit);
ALTER TABLE products ADD CONSTRAINT products_sale_unit_base_fk FOREIGN KEY(sale_unit,product_unit) REFERENCES units(id,base_unit);
ALTER TABLE products ADD CONSTRAINT products_purchase_unit_base_fk FOREIGN KEY(purchase_unit,product_unit) REFERENCES units(id,base_unit);
ALTER TABLE app_users ALTER COLUMN role TYPE varchar(50);
CREATE TABLE ui_settings(key varchar(50) PRIMARY KEY,value varchar(500) NOT NULL);
INSERT INTO ui_settings VALUES ('company_name','MPOS'),('default_language','en'),('currency_symbol',''),('date_format','d-m-y'),('footer','MPOS');
INSERT INTO permissions(name,display_name) VALUES ('manage_setting','Company settings');
INSERT INTO role_permissions SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE r.name='ADMIN' AND p.name='manage_setting';
ALTER TABLE roles ADD COLUMN created_at timestamptz NOT NULL DEFAULT now();
